package com.instrua.waitlist;
import com.instrua.common.exception.NotFoundException; import com.instrua.companies.CompanyRepository; import com.instrua.patients.PatientRepository; import com.instrua.users.CurrentUser; import java.time.Duration; import java.time.Instant; import java.util.List; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class WaitlistService {
 private final WaitlistRepository repository; private final PatientRepository patients; private final CompanyRepository companies; private final WhatsAppCloudService whatsapp;
 public WaitlistService(WaitlistRepository r,PatientRepository p,CompanyRepository c,WhatsAppCloudService w){repository=r;patients=p;companies=c;whatsapp=w;}
 @Transactional public WaitlistEntry join(UUID companyId,WaitlistDtos.JoinRequest request){var company=companies.findById(companyId).orElseThrow(()->new NotFoundException("Clínica não encontrada"));var patient=patients.findByIdAndCompanyIdAndActiveTrue(request.patientId(),companyId).orElseThrow(()->new NotFoundException("Paciente não encontrado nesta clínica"));return repository.save(new WaitlistEntry(company,patient,request.examId(),request.medicalRequestUrl(),request.preferredShifts(),request.priorityLevel()));}
 @Transactional(readOnly=true) public List<WaitlistDtos.QueueItem> queue(UUID companyId,UUID examId){return repository.findQueue(companyId,examId,WaitlistStatus.WAITING).stream().map(w->new WaitlistDtos.QueueItem(w.getId(),w.getPatient().getId(),w.getPatient().getName(),w.getPatient().getPhone(),w.getExamId(),w.getPriorityLevel(),w.getStatus(),w.getCreatedAt())).toList();}
 @Transactional public void callNext(UUID companyId,UUID examId){var candidates=repository.lockNextCandidates(companyId,examId);if(candidates.isEmpty())return;var entry=candidates.get(0);entry.notifyPatient(Instant.now().plus(Duration.ofMinutes(30)));whatsapp.sendAvailabilityMessage(entry.getPatient().getPhone(),entry.getPatient().getName(),entry.getId().toString());}
 @Transactional public void respond(UUID companyId,String phone,boolean accepted){var entries=repository.findNotifiedByPhone(companyId,phone);if(entries.isEmpty())return;var entry=entries.get(0);if(entry.getResponseDeadline()!=null&&entry.getResponseDeadline().isBefore(Instant.now())){entry.expire();callNext(companyId,entry.getExamId());return;}if(accepted)entry.confirm();else{entry.cancel();callNext(companyId,entry.getExamId());}}
}
